use localbrain_core::backend::{db, references, workstreams, Config};
use rusqlite::Connection;
use serde_json::{json, Value};
use std::path::Path;
#[test]
fn exhaustive_workstream_read_models_match_frozen_python() {
    let root = tempfile::tempdir().unwrap();
    let config = Config::for_data_dir(root.path().join("data"));
    let connection = Connection::open_in_memory().unwrap();
    connection.execute_batch(db::SCHEMA).unwrap();
    connection.execute_batch("PRAGMA foreign_keys=OFF").unwrap();
    connection.execute_batch(SQL).unwrap();
    connection.execute_batch("PRAGMA foreign_keys=ON").unwrap();
    let workstream = workstreams::get_workstream(&connection, 1)
        .unwrap()
        .unwrap();
    let bundle = workstreams::build_candidate_bundle(&connection, &workstream).unwrap();
    assert_eq!(bundle["counts"]["sessions"], 148);
    assert_eq!(bundle["counts"]["evidence_items"], 152);
    let views = json!({"get_workstream":workstream,"list_workstreams":workstreams::list_workstreams(&connection,true).unwrap(),"dashboard":workstreams::dashboard_overview(&connection).unwrap(),"picker":workstreams::picker_resources(&connection).unwrap(),"memberships":workstreams::entity_memberships(&connection,"session",1).unwrap(),"candidate_bundle":bundle,"prompt":workstreams::build_prompt(&config,"lb-fixed","organize_resources",Path::new("/synthetic/manifest.json"),Some("{run_id} extra"),true).unwrap(),"render":workstreams::render_structured_result(&json!({"summary":"Synthetic","resource_suggestions":[{"target_thread_id":1,"resource_type":"session","locator":"1","title":"Alpha","evidence":"e-1"}],"checkpoint_draft":{"current_goal":" Alpha "},"priority_review":"Beta"}))});
    let expected: Value = serde_json::from_str(EXPECTED).unwrap();
    for (key, value) in views.as_object().unwrap() {
        assert_eq!(
            references::hash_payload(value),
            expected[key],
            "view {key}: {value}"
        );
    }
}
